class PluginUri{const PluginUri({required this.addonId,required this.path,required this.queryParameters});final String addonId,path;final Map<String,String> queryParameters;factory PluginUri.parse(String source){final u=Uri.parse(source);if(u.scheme!='plugin')throw FormatException('URI precisa usar o esquema plugin://',source);if(u.host.isEmpty)throw FormatException('URI plugin sem addon id.',source);return PluginUri(addonId:u.host,path:u.path.isEmpty?'/':u.path,queryParameters:Map.unmodifiable(u.queryParameters));}@override String toString()=>Uri(scheme:'plugin',host:addonId,path:path,queryParameters:queryParameters.isEmpty?null:queryParameters).toString();}
